 "content": "def transform(grid):
    n = len(grid)
    if not n or any(len(row) != n for row in grid):
        raise ValueError("expected a non-empty square grid")

    def rotate_cw(g):
        return [list(row) for row in zip(*g[::-1])]

    def rotate_ccw(g):
        return [list(row) for row in zip(*g)][::-1]

    def rotate_180(g):
        return [row[::-1] for row in g[::-1]]

    cw = rotate_cw(grid)
    ccw = rotate_ccw(grid)
    half = rotate_180(grid)
    return [list(grid[r]) + cw[r] for r in range(n)] + [ccw[r] + half[r] for r in range(n)]
